const input = $input.first()?.json ?? $json ?? {};
const records = Array.isArray(input.records)
  ? input.records
  : Array.isArray(input.parsed_records)
    ? input.parsed_records
    : [];
if (!input.run_id) throw new Error('run_id is required.');
if (!input.location_key) throw new Error('location_key is required.');
if (!input.source_scope_key) throw new Error('source_scope_key is required.');
if (records.length > 200) throw new Error('Facebook enricher accepts at most 200 records.');
function text(v){return v==null?'':String(v).normalize('NFKC').trim().replace(/\s+/g,' ')}
function phone(v){const d=text(v).replace(/\D/g,'');return d.length>=7&&d.length<=15}
function email(v){return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(text(v))}
function website(v){return /^https?:\/\/[^\s/]+\.[^\s/]+/i.test(text(v))&&!/^https?:\/\/(?:www\.)?facebook\.com\//i.test(text(v))}
function hash(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return (h>>>0).toString(16).padStart(8,'0')}
const threshold=Math.min(3,Math.max(1,Number(input.facebook_missing_field_threshold??2)));
const maxCandidates=Math.min(50,Math.max(1,Number(input.facebook_max_candidates??20)));
const resultsPerCandidate=Math.min(5,Math.max(1,Number(input.facebook_results_per_candidate??3)));
const location=input.location||{};
const locationDisplay=text(location.location_display||[location.city,location.region||location.state,location.country].filter(Boolean).join(', '));
const prepared=records.map(r=>({...r}));
const eligible=[];
for(let i=0;i<prepared.length;i++){
  const r=prepared[i];
  const missing=[!phone(r.phone)?'phone':null,!email(r.email)?'email':null,!website(r.website)?'website':null].filter(Boolean);
  const businessName=text(r.business_name);
  const alreadyChecked=Boolean(r.facebook_enrichment?.checked_at);
  const canSearch=Boolean(businessName&&locationDisplay&&!alreadyChecked&&missing.length>=threshold&&eligible.length<maxCandidates);
  if(canSearch){
    eligible.push({record_index:i,lead_fingerprint:text(r.lead_fingerprint),business_name:businessName,city:text(r.city||location.city),region:text(r.region||r.state||location.region||location.state),region_code:text(r.region_code||r.state_code||location.region_code||location.state_code),country:text(r.country||location.country),phone:text(r.phone),email:text(r.email),website:text(r.website),address:text(r.address),missing_fields:missing});
    r.facebook_enrichment={schema_version:'a1.facebook-business-enrichment.v1',status:'pending',missing_fields_before:missing,checked_at:null};
  }else if(!r.facebook_enrichment){
    r.facebook_enrichment={schema_version:'a1.facebook-business-enrichment.v1',status:alreadyChecked?'already_checked':'skipped_not_needed',missing_fields_before:missing,checked_at:null};
  }
}
const categories=[...new Set(eligible.map(c=>c.business_name))];
const resultsLimit=Math.min(100,Math.max(1,categories.length*resultsPerCandidate));
const requestMaterial=JSON.stringify({run_id:input.run_id,source_job_id:input.source_job_id||'',source_scope_key:input.source_scope_key,location_key:input.location_key,categories,locationDisplay,resultsLimit});
const requestKey=`facebook-v1:${hash(requestMaterial)}`;
return [{json:{source_envelope:input,prepared_records:prepared,facebook_candidates:eligible,facebook_needed:eligible.length>0,facebook_request_key:requestKey,facebook_actor_input:{categories,locations:locationDisplay?[locationDisplay]:[],resultsLimit},facebook_results_limit:resultsLimit,facebook_max_total_charge_usd:Math.min(2,Math.max(0.05,Number(input.facebook_max_total_charge_usd??1))),facebook_actor_build_tag:text(input.facebook_actor_build_tag||'latest'),facebook_started_at:new Date().toISOString()}}];
